    eval(s, me) { let v = 0; s.b.forEach((p, i) => { if (!p) return; const own = p.toLowerCase() === (me ? 'b' : 'a'); const x = p === 'A' || p === 'B' ? (flying ? 300 : 160) : 100; v += own ? x : -x; }); return giveaway ? -v : v; },
