TB.threecheck = chessVariant({ init: () => ({ ...TB.chess.init(), checks: [0, 0] }),
  play(s, m) { const n = chMake(s, m); n.checks = (s.checks || [0, 0]).slice(); if (chCheck(n)) n.checks[s.t]++; return n; },
  result(s, ms) { const c = s.checks || [0, 0]; if (c[0] >= 3) return { winner: 0 }; if (c[1] >= 3) return { winner: 1 }; return TB.chess.result(s, ms); }, moves(s) { const c = s.checks || [0, 0]; return c[0] >= 3 || c[1] >= 3 ? [] : TB.chess.moves(s); },
  eval(s, me) { const c = s.checks || [0, 0]; return TB.chess.eval(s, me) + (c[me] - c[1 - me]) * 300; },
  view(s, x) { TB.chess.view(s, x); x.el.insertAdjacentHTML('afterbegin', `<div class="score2"><span>White checks ${(s.checks || [0, 0])[0]}/3</span><span>Black checks ${(s.checks || [0, 0])[1]}/3</span></div>`); } });
