TB.hareandhounds = { seats: ['Hounds', 'Hare'], init: () => ({ hounds: [3, 0, 8], hare: 7, t: 0, n: 0 }), turn: s => s.t,
  moves(s) { if (TB.hareandhounds.result(s)) return []; const occ = new Set([...s.hounds, s.hare]); if (s.t === 1) return HH_ADJ[s.hare].filter(j => !occ.has(j)).map(t => ({ f: s.hare, t }));
    const out = []; s.hounds.forEach(h => HH_ADJ[h].forEach(j => { if (!occ.has(j) && HH_P[j][0] >= HH_P[h][0]) out.push({ f: h, t: j }); })); return out; },
  play(s, m) { if (s.t === 1) return { ...s, hare: m.t, t: 0, n: s.n + 1 }; return { ...s, hounds: s.hounds.map(h => h === m.f ? m.t : h), t: 1, n: s.n + 1 }; },
  result(s) { const occ = new Set([...s.hounds, s.hare]); if (!HH_ADJ[s.hare].some(j => !occ.has(j))) return { winner: 0 }; if (HH_P[s.hare][0] <= Math.min(...s.hounds.map(h => HH_P[h][0]))) return { winner: 1 }; if (s.n >= 60) return { winner: 1 }; return null; },
  eval(s, me) { const occ = new Set([...s.hounds, s.hare]), free = HH_ADJ[s.hare].filter(j => !occ.has(j)).length, adv = HH_P[s.hare][0] - Math.min(...s.hounds.map(h => HH_P[h][0])); const v = -free * 10 + adv * 8 + sum(s.hounds.map(h => HH_P[h][0])) * 3; return me === 0 ? v : -v; }, depth: l => Math.min(8, l), budget: 900,
  view(s, x) { const ms = x.can ? TB.hareandhounds.moves(s) : []; const sel = x.sel, src = new Set(ms.map(m => m.f)), tg = new Map(); if (sel != null) ms.filter(m => m.f === sel).forEach(m => tg.set(m.t, m)); const P = i => [10 + HH_P[i][0] * 20, 15 + HH_P[i][1] * 25];
    x.el.innerHTML = `<svg class="bd mor" viewBox="0 0 100 70">${HH_E.map(([a, b]) => { const [x1, y1] = P(a), [x2, y2] = P(b); return `<line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}"/>`; }).join('')}${HH_P.map((_, i) => { const [cx, cy] = P(i), hound = s.hounds.includes(i), hare = s.hare === i; return `<g data-i="${i}" class="${src.has(i) || tg.has(i) ? 'tg' : ''}${sel === i ? ' sel' : ''}"><circle cx="${cx}" cy="${cy}" r="6.5" class="hit"/>${hound ? `<circle cx="${cx}" cy="${cy}" r="5.5" fill="#8b5a2b"/>` : hare ? `<circle cx="${cx}" cy="${cy}" r="5.5" fill="#f6f6f2"/>` : `<circle cx="${cx}" cy="${cy}" r="1.6" class="pt"/>`}</g>`; }).join('')}</svg><p class="muted small">Hounds (brown) may not move backwards. The hare (white) escapes by getting behind every hound or surviving 60 moves.</p>`;
    x.on(d => { const i = +d; if (tg.has(i)) { x.sel = null; x.act(tg.get(i)); } else if (src.has(i)) { x.sel = i; x.redraw(); } }); } };

// ---------- Tafl family ----------
function taflGame({ N, att, def, king, edgeEscape }) { const TH = king, CORN = new Set([0, N - 1, N * N - N, N * N - 1]); const D4 = [[1, 0], [-1, 0], [0, 1], [0, -1]];
  const G = { seats: ['Attackers', 'Defenders'], init() { const b = Array(N * N).fill(0); att.forEach(i => b[i] = 1); def.forEach(i => b[i] = 2); b[king] = 3; return { b, t: 0, n: 0 }; }, turn: s => s.t,
    moves(s) { if (G.result(s)) return []; const out = [], b = s.b, mine = v => s.t === 0 ? v === 1 : v === 2 || v === 3; b.forEach((v, i) => { if (!mine(v)) return; const r = i / N | 0, c = i % N; for (const [dr, dc] of D4) { let rr = r + dr, cc = c + dc; while (rr >= 0 && rr < N && cc >= 0 && cc < N && !b[rr * N + cc]) { const j = rr * N + cc; if (v === 3 || ((edgeEscape || !CORN.has(j)) && j !== TH)) out.push({ f: i, t: j }); if (j === TH && v !== 3) break; rr += dr; cc += dc; } } }); return out; },
    play(s, m) { const b = s.b.slice(), v = b[m.f]; b[m.t] = v; b[m.f] = 0; const r = m.t / N | 0, c = m.t % N, att2 = v === 1; const hostile = j => (!edgeEscape && CORN.has(j)) || (j === TH && !b[j]) || (att2 ? b[j] === 1 : b[j] === 2 || b[j] === 3);
      for (const [dr, dc] of D4) { const rr = r + dr, cc = c + dc, r2 = r + 2 * dr, c2 = c + 2 * dc; if (rr < 0 || rr >= N || cc < 0 || cc >= N || r2 < 0 || r2 >= N || c2 < 0 || c2 >= N) continue; const q = rr * N + cc; if ((att2 && b[q] === 2) || (!att2 && b[q] === 1)) if (hostile(r2 * N + c2)) b[q] = 0; }
      return { b, t: 1 - s.t, n: s.n + 1, last: [m.f, m.t] }; },
    result(s) { const k = s.b.indexOf(3); if (k < 0) return { winner: 0 }; const r = k / N | 0, c = k % N; if (edgeEscape ? (r === 0 || c === 0 || r === N - 1 || c === N - 1) : CORN.has(k)) return { winner: 1 };
      if (D4.every(([dr, dc]) => { const rr = r + dr, cc = c + dc; if (rr < 0 || rr >= N || cc < 0 || cc >= N) return false; const j = rr * N + cc; return s.b[j] === 1 || j === TH; })) return { winner: 0 };
      if (!s.b.includes(1)) return { winner: 1 }; if (s.n >= 250) return { winner: -1 }; return null; },
    eval(s, me) { const k = s.b.indexOf(3); if (k < 0) return me === 0 ? 1e6 : -1e6; const r = k / N | 0, c = k % N, ed = Math.min(r, c, N - 1 - r, N - 1 - c); let adj = 0; D4.forEach(([dr, dc]) => { const rr = r + dr, cc = c + dc; if (rr >= 0 && rr < N && cc >= 0 && cc < N && s.b[rr * N + cc] === 1) adj++; });
      const v = s.b.filter(x => x === 1).length * 10 - s.b.filter(x => x === 2).length * 16 + adj * 25 + ed * 15; return me === 0 ? v : -v; }, depth: l => l <= 5 ? 1 : 2, budget: 900,
    view(s, x) { selMoveView(x, x.can ? G.moves(s) : [], s, (src, tg, sel) => `<div class="bd tafl" style="grid-template-columns:repeat(${N},1fr);max-width:${N * 52}px">${s.b.map((v, i) => `<button data-i="${i}" class="${(!edgeEscape && CORN.has(i)) || i === TH ? 'sp' : ''} ${sel === i ? 'sel' : ''} ${tg.has(i) ? 'tg' : ''} ${(s.last || []).includes(i) ? 'last' : ''}" ${src.has(i) || tg.has(i) ? '' : 'disabled'}>${v ? `<i class="tf${v}"></i>` : ''}</button>`).join('')}</div><p class="muted small">The king (gold) escapes to ${edgeEscape ? 'any edge' : 'a corner'}; attackers capture him by surrounding all four sides.</p>`); } }; return G; }
TB.tablut = taflGame({ N: 9, king: 40, edgeEscape: true, att: [3, 4, 5, 13, 27, 36, 45, 37, 35, 44, 53, 43, 75, 76, 77, 67], def: [22, 31, 38, 39, 41, 42, 49, 58] });
TB.brandubh = taflGame({ N: 7, king: 24, edgeEscape: false, att: [3, 10, 21, 22, 26, 27, 38, 45], def: [17, 31, 23, 25] });

// ---------- Hasami Shogi ----------
TB.hasami = { seats: ['Black (bottom)', 'White (top)'], init() { const b = Array(81).fill(-1); for (let c = 0; c < 9; c++) { b[c] = 1; b[72 + c] = 0; } return { b, t: 0, n: 0 }; }, turn: s => s.t,
  moves(s) { if (TB.hasami.result(s)) return []; const out = []; s.b.forEach((v, i) => { if (v !== s.t) return; const r = i / 9 | 0, c = i % 9; for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { let rr = r + dr, cc = c + dc; while (rr >= 0 && rr < 9 && cc >= 0 && cc < 9 && s.b[rr * 9 + cc] < 0) { out.push({ f: i, t: rr * 9 + cc }); rr += dr; cc += dc; } } }); return out; },
  play(s, m) { const b = s.b.slice(), t = s.t; b[m.t] = t; b[m.f] = -1; const r = m.t / 9 | 0, c = m.t % 9;
    for (const [dr, dc] of [[1, 0], [-1, 0], [0, 1], [0, -1]]) { const line = []; let rr = r + dr, cc = c + dc; while (rr >= 0 && rr < 9 && cc >= 0 && cc < 9 && b[rr * 9 + cc] === 1 - t) { line.push(rr * 9 + cc); rr += dr; cc += dc; } if (line.length && rr >= 0 && rr < 9 && cc >= 0 && cc < 9 && b[rr * 9 + cc] === t) line.forEach(i => b[i] = -1); }
    return { b, t: 1 - t, n: s.n + 1, last: [m.f, m.t] }; },
  result(s) { const a = s.b.filter(v => v === 0).length, c = s.b.filter(v => v === 1).length; if (c <= 3) return { winner: 0 }; if (a <= 3) return { winner: 1 }; if (s.n > 200) return { winner: a > c ? 0 : c > a ? 1 : -1 }; return null; },
  eval(s, me) { return (s.b.filter(v => v === me).length - s.b.filter(v => v === 1 - me).length) * 10; }, depth: l => l <= 5 ? 1 : 2, budget: 900,
  view(s, x) { selMoveView(x, x.can ? TB.hasami.moves(s) : [], s, (src, tg, sel) => `<div class="bd shogi">${s.b.map((v, i) => `<button data-i="${i}" class="${sel === i ? 'sel' : ''} ${tg.has(i) ? 'tg' : ''} ${(s.last || []).includes(i) ? 'last' : ''}" ${src.has(i) || tg.has(i) ? '' : 'disabled'}>${v >= 0 ? `<span class="shp ${v ? 'g' : ''}">歩</span>` : ''}</button>`).join('')}</div><p class="muted small">Sandwich enemy pieces in a line to capture them. Reduce the opponent to three pieces to win.</p>`); } };

// ---------- Sim ----------
const SIM_E = []; for (let a = 0; a < 6; a++) for (let b = a + 1; b < 6; b++) SIM_E.push([a, b]);
const simTri = (e, p) => { for (let a = 0; a < 6; a++) for (let b = a + 1; b < 6; b++) for (let c = b + 1; c < 6; c++) { const ix = (x, y) => SIM_E.findIndex(q => q[0] === x && q[1] === y); if (e[ix(a, b)] === p && e[ix(a, c)] === p && e[ix(b, c)] === p) return true; } return false; };
TB.sim = { seats: ['Red', 'Blue'], init: () => ({ e: Array(15).fill(-1), t: 0 }), turn: s => s.t,
  moves: s => TB.sim.result(s) ? [] : s.e.map((v, i) => v < 0 ? i : -1).filter(i => i >= 0), play: (s, m) => { const e = s.e.slice(); e[m] = s.t; return { e, t: 1 - s.t, last: m }; },
  result: s => simTri(s.e, 0) ? { winner: 1 } : simTri(s.e, 1) ? { winner: 0 } : null,
  eval(s, me) { const risk = p => { let n = 0; for (let i = 0; i < 15; i++) if (s.e[i] < 0) { const e = s.e.slice(); e[i] = p; if (simTri(e, p)) n++; } return n; }; return risk(1 - me) - risk(me); }, depth: l => Math.min(6, Math.ceil(l / 1.6)), budget: 1000,
  view(s, x) { const P = i => [50 + 38 * Math.cos(i * Math.PI / 3 - Math.PI / 2), 50 + 38 * Math.sin(i * Math.PI / 3 - Math.PI / 2)];
    x.el.innerHTML = `<svg class="bd simb" viewBox="0 0 100 100">${SIM_E.map(([a, b], i) => { const [x1, y1] = P(a), [x2, y2] = P(b), v = s.e[i]; return `<g data-i="${v < 0 && x.can ? i : ''}"><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" class="simhit"/><line x1="${x1}" y1="${y1}" x2="${x2}" y2="${y2}" stroke="${v >= 0 ? SEATCOL[v] : '#ffffff40'}" stroke-width="${v >= 0 ? 2.2 : 1}" ${i === s.last ? 'stroke-dasharray="3 1.5"' : ''}/></g>`; }).join('')}${[0, 1, 2, 3, 4, 5].map(i => { const [cx, cy] = P(i); return `<circle cx="${cx}" cy="${cy}" r="3" fill="#fff"/>`; }).join('')}</svg><p class="muted small">Tap a grey line to colour it. Whoever completes a triangle in their own colour loses.</p>`;
    x.on(d => d !== '' && x.act(+d)); } };

// ---------- Dice: Shut the Box ----------
const subsetsSum = (tiles, n) => { const out = []; const rec = (i, cur, s2) => { if (s2 === n) { out.push(cur.slice()); return; } if (s2 > n) return; for (let k = i; k < tiles.length; k++) { cur.push(tiles[k]); rec(k + 1, cur, s2 + tiles[k]); cur.pop(); } }; rec(0, [], 0); return out; };
TB.shutbox = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], init: n => ({ n, open: [...Array(9)].map((_, i) => i + 1), roll: 0, dice: [], t: 0, scores: Array(n).fill(null), log: '' }), turn: s => s.t,
  moves(s) { if (TB.shutbox.result(s)) return []; if (!s.roll) return ['roll']; const opts = subsetsSum(s.open, s.roll); return opts.length ? opts.map(t => ({ t })) : ['end']; },
  play(s, m) { const n = cl(s); const finish = () => { n.scores[s.t] = sum(n.open); n.log = `Seat ${s.t + 1} finished with ${n.scores[s.t]}`; n.t = (s.t + 1) % s.n; n.open = [...Array(9)].map((_, i) => i + 1); n.roll = 0; n.dice = []; };
    if (m === 'roll') { const one = sum(s.open) <= 6; n.dice = one ? [roll6()] : [roll6(), roll6()]; n.roll = sum(n.dice); return n; } if (m === 'end') { finish(); return n; }
    n.open = s.open.filter(v => !m.t.includes(v)); n.roll = 0; if (!n.open.length) { n.scores[s.t] = 0; n.log = `Seat ${s.t + 1} shut the box!`; n.shut = s.t; } return n; },
  result(s) { if (s.shut !== undefined) return { winner: s.shut }; if (s.scores.some(v => v === null)) return null; const mn = Math.min(...s.scores); return { winner: s.scores.filter(v => v === mn).length > 1 ? -1 : s.scores.indexOf(mn), score: s.scores }; },
  ai(s, level, ms) { if (typeof ms[0] === 'string') return ms[0]; return pickBest(ms, m => (level >= 5 ? -m.t.length * 2 + Math.max(...m.t) : 0), level); },
  view(s, x) { const ms = x.can ? TB.shutbox.moves(s) : [], sel = x.sel || []; const okSel = s.roll && sum(sel) === s.roll && ms.some(m => m.t && m.t.slice().sort().join() === sel.slice().sort().join());
    x.el.innerHTML = `<div class="pig"><div class="pigs">${s.scores.map((v, i) => `<div class="pg ${i === s.t ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span><b>${v === null ? '–' : v}</b></div>`).join('')}</div><div class="sbox">${[1, 2, 3, 4, 5, 6, 7, 8, 9].map(v => `<button data-i="v${v}" class="${s.open.includes(v) ? '' : 'shut'} ${sel.includes(v) ? 'sel' : ''}" ${x.can && s.roll && s.open.includes(v) ? '' : 'disabled'}>${v}</button>`).join('')}</div>
      <div class="dice">${s.dice.map(diceFace).join('')}</div><p>${s.roll ? `Rolled <b>${s.roll}</b>: shut tiles adding up to it.` : ''} <span class="muted small">${esc(s.log)}</span></p><div class="row-btns">${ms.includes('roll') ? '<button class="btn hot" data-i="roll">Roll</button>' : ''}${s.roll && ms[0] !== 'end' ? `<button class="btn hot" data-i="go" ${okSel ? '' : 'disabled'}>Shut ${sel.join(' + ') || 'tiles'}</button>` : ''}${ms.includes('end') ? '<button class="btn" data-i="end">No way to make it: end turn</button>' : ''}</div><p class="muted small">Lowest total of open tiles wins.</p></div>`;
    x.on(d => { if (d === 'roll' || d === 'end') return x.act(d); if (d === 'go') { const t = sel.slice(); x.sel = []; return x.act(ms.find(m => m.t && m.t.slice().sort().join() === t.slice().sort().join())); } const v = +d.slice(1); x.sel = sel.includes(v) ? sel.filter(q => q !== v) : sel.concat(v); x.redraw(); }); } };

// ---------- Dice: Bunco ----------
TB.bunco = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], init: n => ({ n, round: 1, pts: Array(n).fill(0), wins: Array(n).fill(0), buncos: Array(n).fill(0), t: 0, dice: [], log: 'Round 1: roll for ones.' }), turn: s => s.t,
  moves: s => TB.bunco.result(s) ? [] : ['roll'],
  play(s) { const n = cl(s), d = [roll6(), roll6(), roll6()], r = s.round; n.dice = d; let p = d.filter(v => v === r).length; if (d.every(v => v === r)) { p = 21; n.buncos[s.t]++; n.log = `Seat ${s.t + 1}: BUNCO!`; } else if (d[0] === d[1] && d[1] === d[2]) { p = 5; n.log = `Seat ${s.t + 1}: three of a kind, 5 points`; } else n.log = `Seat ${s.t + 1} scored ${p}`;
    n.pts[s.t] += p; if (n.pts[s.t] >= 21) { n.wins[s.t]++; n.log += ` and wins round ${r}!`; n.round++; n.pts = n.pts.map(() => 0); n.t = s.t; } else if (!p) n.t = (s.t + 1) % s.n; return n; },
  result(s) { if (s.round <= 6) return null; const sc = s.wins.map((w, i) => w * 100 + s.buncos[i]), mx = Math.max(...sc); return { winner: sc.filter(v => v === mx).length > 1 ? -1 : sc.indexOf(mx), score: s.wins }; },
  ai: () => 'roll',
  view(s, x) { x.el.innerHTML = `<div class="pig"><p>Round <b>${Math.min(s.round, 6)}</b> of 6 · target number <b>${Math.min(s.round, 6)}</b></p><div class="pigs">${s.pts.map((v, i) => `<div class="pg ${i === s.t ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span><b>${v}</b><small>rounds ${s.wins[i]} · buncos ${s.buncos[i]}</small><div class="bar"><i style="width:${Math.min(100, v / 21 * 100)}%"></i></div></div>`).join('')}</div><div class="dice">${s.dice.map(diceFace).join('')}</div><p class="muted small">${esc(s.log)}</p><button class="btn hot" data-i="roll" ${x.can ? '' : 'disabled'}>Roll three dice</button><p class="muted small">Score one point per die showing the round number and keep rolling; three of them is a Bunco (21). First to 21 takes the round.</p></div>`; x.on(() => x.act('roll')); } };

// ---------- Dice: Poker Dice ----------
const pdRank = d => { const c = [0, 0, 0, 0, 0, 0, 0]; d.forEach(v => c[v]++); const g = c.map((n, v) => [n, v]).filter(x => x[0]).sort((a, b) => b[0] - a[0] || b[1] - a[1]); const u = [...new Set(d)].sort((a, b) => a - b), st = u.length === 5 && u[4] - u[0] === 4;
  const cat = g[0][0] === 5 ? 7 : g[0][0] === 4 ? 6 : g[0][0] === 3 && g[1][0] === 2 ? 5 : st ? 4 : g[0][0] === 3 ? 3 : g[0][0] === 2 && g[1][0] === 2 ? 2 : g[0][0] === 2 ? 1 : 0; return cat * 1e5 + g.reduce((a, x, i) => a + x[1] * 10 ** (4 - i), 0); };
const PD_N = ['High dice', 'One pair', 'Two pairs', 'Three of a kind', 'Straight', 'Full house', 'Four of a kind', 'Five of a kind'];
TB.pokerdice = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], init: n => ({ n, round: 1, wins: Array(n).fill(0), best: Array(n).fill(null), d: [1, 1, 1, 1, 1], held: [0, 0, 0, 0, 0], rolls: 0, t: 0, log: '' }), turn: s => s.t,
  moves(s) { if (TB.pokerdice.result(s)) return []; const out = []; if (s.rolls < 3) out.push('roll'); if (s.rolls > 0) { out.push('stand'); if (s.rolls < 3) for (let i = 0; i < 5; i++) out.push({ h: i }); } return out; },
  play(s, m) { const n = cl(s); if (m === 'roll') { n.d = n.d.map((v, i) => n.held[i] ? v : roll6()); n.rolls++; if (n.rolls < 3) return n; m = 'stand'; } if (m.h !== undefined) { n.held[m.h] ^= 1; return n; }
    n.best[s.t] = pdRank(n.d); n.hands = n.hands || {}; n.log = `Seat ${s.t + 1}: ${PD_N[Math.floor(n.best[s.t] / 1e5)]}`; n.d = [1, 1, 1, 1, 1]; n.held = [0, 0, 0, 0, 0]; n.rolls = 0;
    if (s.t === s.n - 1) { const mx = Math.max(...n.best), w = n.best.indexOf(mx); if (n.best.filter(v => v === mx).length === 1) n.wins[w]++; n.log += ` · round to Seat ${w + 1}`; n.round++; n.best = Array(s.n).fill(null); n.t = 0; } else n.t = s.t + 1; return n; },
  result(s) { if (s.round <= 3) return null; const mx = Math.max(...s.wins); return { winner: s.wins.filter(v => v === mx).length > 1 ? -1 : s.wins.indexOf(mx), score: s.wins }; },
  ai(s, level, ms) { if (!s.rolls) return 'roll'; const cat = Math.floor(pdRank(s.d) / 1e5); if (s.rolls >= 3 || cat >= (level >= 6 ? 5 : 3) || !ms.includes('roll')) return 'stand'; const c = [0, 0, 0, 0, 0, 0, 0]; s.d.forEach(v => c[v]++); const keepV = c.indexOf(Math.max(...c)); const want = s.d.map(v => c[v] >= 2 && (v === keepV || c[v] >= 2) ? 1 : 0); for (let i = 0; i < 5; i++) if (want[i] !== s.held[i]) return { h: i }; return 'roll'; },
  view(s, x) { const ms = x.can ? TB.pokerdice.moves(s) : []; x.el.innerHTML = `<div class="yacht"><p class="center">Round ${Math.min(s.round, 3)} of 3 · rounds won ${s.wins.map((w, i) => esc(x.names[i] || '') + ' ' + w).join(' · ')}</p><div class="dice">${s.d.map((v, i) => `<button class="dbtn ${s.held[i] ? 'held' : ''}" data-i="h${i}" ${ms.some(m => m.h === i) ? '' : 'disabled'}>${s.rolls ? diceFace(v) : '<span class="die blank"></span>'}<small>${s.held[i] ? 'Held' : ''}</small></button>`).join('')}</div>
    <p class="center">${s.rolls ? PD_N[Math.floor(pdRank(s.d) / 1e5)] : ''} <span class="muted small">${esc(s.log)}</span></p><div class="row-btns"><button class="btn hot" data-i="roll" ${ms.includes('roll') ? '' : 'disabled'}>${s.rolls ? `Roll again (${3 - s.rolls} left)` : 'Roll'}</button><button class="btn" data-i="stand" ${ms.includes('stand') ? '' : 'disabled'}>Stand</button></div></div>`;
    x.on(d => x.act(d[0] === 'h' ? { h: +d.slice(1) } : d)); } };

// ---------- Dice: Cee-lo ----------
const ceeVal = d => { const s3 = d.slice().sort(); if (s3.join() === '4,5,6') return 1000; if (s3.join() === '1,2,3') return -1; if (s3[0] === s3[2]) return 100 + s3[0]; if (s3[0] === s3[1]) return s3[2]; if (s3[1] === s3[2]) return s3[0]; return null; };
TB.ceelo = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4', 'Seat 5', 'Seat 6'], init: n => ({ n, round: 1, wins: Array(n).fill(0), val: Array(n).fill(null), dice: [], t: 0, log: '' }), turn: s => s.t,
  moves: s => TB.ceelo.result(s) ? [] : ['roll'],
  play(s) { const n = cl(s), d = [roll6(), roll6(), roll6()], v = ceeVal(d); n.dice = d; if (v === null) { n.log = 'No score, roll again'; return n; } n.val[s.t] = v; n.log = `Seat ${s.t + 1}: ${v === 1000 ? '4-5-6!' : v === -1 ? '1-2-3' : v > 100 ? 'triple ' + (v - 100) + 's' : 'point ' + v}`;
    if (s.t === s.n - 1) { const mx = Math.max(...n.val), w = n.val.indexOf(mx); if (n.val.filter(x => x === mx).length === 1) n.wins[w]++; n.log += ` · round to Seat ${w + 1}`; n.round++; n.val = Array(s.n).fill(null); n.t = 0; } else n.t = s.t + 1; return n; },
  result(s) { if (s.round <= 5) return null; const mx = Math.max(...s.wins); return { winner: s.wins.filter(v => v === mx).length > 1 ? -1 : s.wins.indexOf(mx), score: s.wins }; }, ai: () => 'roll',
  view(s, x) { x.el.innerHTML = `<div class="pig"><p>Round ${Math.min(s.round, 5)} of 5</p><div class="pigs">${s.wins.map((w, i) => `<div class="pg ${i === s.t ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span><b>${w}</b><small>${s.val[i] === null ? '' : s.val[i] === 1000 ? '4-5-6' : s.val[i] === -1 ? '1-2-3' : s.val[i] > 100 ? 'triple' : 'point ' + s.val[i]}</small></div>`).join('')}</div><div class="dice">${s.dice.map(diceFace).join('')}</div><p class="muted small">${esc(s.log)}</p><button class="btn hot" data-i="roll" ${x.can ? '' : 'disabled'}>Roll three dice</button><p class="muted small">4-5-6 beats everything, then triples, then a pair's odd die (the point). 1-2-3 loses.</p></div>`; x.on(() => x.act('roll')); } };

// ---------- Dice: Midnight (1-4-24) ----------
TB.midnight = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], init: n => ({ n, round: 1, tot: Array(n).fill(0), last: Array(n).fill(null), d: [], kept: [], sel: [], t: 0, log: '' }), turn: s => s.t,
  moves(s) { if (TB.midnight.result(s)) return []; if (!s.d.length) return ['roll']; const out = s.d.map((_, i) => ({ k: i })); if (s.sel.length) out.push('roll'); return out; },
  play(s, m) { const n = cl(s); if (m.k !== undefined) { const i = n.sel.indexOf(m.k); i >= 0 ? n.sel.splice(i, 1) : n.sel.push(m.k); return n; }
    if (s.d.length) { n.kept = n.kept.concat(s.sel.map(i => s.d[i])); n.sel = []; } const left = 6 - n.kept.length; if (left) { n.d = ldRoll(left); if (left === 6 || true) return n; }
    const k = n.kept, ok = k.includes(1) && k.includes(4); let sc = 0; if (ok) { const rest = k.slice(); rest.splice(rest.indexOf(1), 1); rest.splice(rest.indexOf(4), 1); sc = sum(rest); } n.last[s.t] = sc; n.tot[s.t] += sc; n.log = `Seat ${s.t + 1}: ${ok ? 'qualified with ' + sc : 'did not qualify'}`; n.kept = []; n.d = []; n.sel = []; if (s.t === s.n - 1) { n.round++; n.t = 0; } else n.t = s.t + 1; return n; },
  result(s) { if (s.round <= 3) return null; const mx = Math.max(...s.tot); return { winner: s.tot.filter(v => v === mx).length > 1 ? -1 : s.tot.indexOf(mx), score: s.tot }; },
  ai(s, level, ms) { if (!s.d.length) return 'roll'; const need1 = !s.kept.includes(1), need4 = !s.kept.includes(4); const want = new Set(); s.d.forEach((v, i) => { if (v === 1 && need1 && ![...want].some(j => s.d[j] === 1)) want.add(i); else if (v === 4 && need4 && ![...want].some(j => s.d[j] === 4)) want.add(i); else if (v >= (level >= 5 ? 5 : 4) && !(v === 4 && need4)) want.add(i); });
    if (!want.size) { let bi = 0; s.d.forEach((v, i) => { if (v > s.d[bi]) bi = i; }); want.add(bi); } for (let i = 0; i < s.d.length; i++) if (want.has(i) !== s.sel.includes(i)) return { k: i }; return 'roll'; },
  view(s, x) { const ms = x.can ? TB.midnight.moves(s) : []; x.el.innerHTML = `<div class="pig"><p>Round ${Math.min(s.round, 3)} of 3</p><div class="pigs">${s.tot.map((v, i) => `<div class="pg ${i === s.t ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span><b>${v}</b><small>${s.last[i] === null ? '' : 'last ' + s.last[i]}</small></div>`).join('')}</div>
    <p>Kept: ${s.kept.map(diceFace).join('') || 'none yet'}</p><div class="dice">${s.d.map((v, i) => `<button class="dbtn ${s.sel.includes(i) ? 'held' : ''}" data-i="k${i}" ${x.can ? '' : 'disabled'}>${diceFace(v)}</button>`).join('')}</div><p class="muted small">${esc(s.log)}</p>
    <button class="btn hot" data-i="roll" ${ms.includes('roll') ? '' : 'disabled'}>${s.d.length ? (6 - s.kept.length - s.sel.length ? 'Keep selected and roll the rest' : 'Keep selected and score') : 'Roll six dice'}</button><p class="muted small">Keep at least one die each roll. You need a 1 and a 4 to qualify; the other four dice are your score (24 is perfect).</p></div>`;
    x.on(d => x.act(d === 'roll' ? 'roll' : { k: +d.slice(1) })); } };
// fix midnight scoring once all six are kept
const _mdPlay = TB.midnight.play; TB.midnight.play = (s, m) => { if (m === 'roll' && s.d.length && s.kept.length + s.sel.length === 6) { const n = cl(s); n.kept = n.kept.concat(s.sel.map(i => s.d[i])); n.sel = []; n.d = []; const k = n.kept, ok = k.includes(1) && k.includes(4); let sc = 0; if (ok) { const rest = k.slice(); rest.splice(rest.indexOf(1), 1); rest.splice(rest.indexOf(4), 1); sc = sum(rest); } n.last[s.t] = sc; n.tot[s.t] += sc; n.log = `Seat ${s.t + 1}: ${ok ? 'qualified with ' + sc : 'did not qualify'}`; n.kept = []; if (s.t === s.n - 1) { n.round++; n.t = 0; } else n.t = s.t + 1; return n; } return _mdPlay(s, m); };

// ---------- Dice: Beetle ----------
const BEETLE = { 6: 'body', 5: 'head', 4: 'leg', 3: 'eye', 2: 'antenna', 1: 'tail' }, BMAX = { body: 1, head: 1, leg: 6, eye: 2, antenna: 2, tail: 1 };
const beetleNeed = (b, v) => { const p = BEETLE[v]; if ((b[p] || 0) >= BMAX[p]) return false; if (p === 'body') return true; if (!b.body) return false; if ((p === 'eye' || p === 'antenna') && !b.head) return false; return true; };
TB.beetle = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], init: n => ({ n, b: [...Array(n)].map(() => ({})), t: 0, die: 0, log: 'Roll a 6 to start your beetle.' }), turn: s => s.t,
  moves: s => TB.beetle.result(s) ? [] : ['roll'],
  play(s) { const n = cl(s), v = roll6(); n.die = v; if (beetleNeed(n.b[s.t], v)) { const p = BEETLE[v]; n.b[s.t][p] = (n.b[s.t][p] || 0) + 1; n.log = `Seat ${s.t + 1} rolled ${v}: drew a ${p}. Roll again!`; } else { n.log = `Seat ${s.t + 1} rolled ${v}: nothing to draw.`; n.t = (s.t + 1) % s.n; } return n; },
  result: s => { const w = s.b.findIndex(b => Object.entries(BMAX).every(([k, m]) => (b[k] || 0) >= m)); return w >= 0 ? { winner: w } : null; }, ai: () => 'roll',
  view(s, x) { const draw = b => `<svg viewBox="0 0 60 80" class="beetle">${b.body ? '<ellipse cx="30" cy="48" rx="14" ry="20" fill="#19a974"/>' : '<ellipse cx="30" cy="48" rx="14" ry="20" fill="none" stroke="#ffffff30" stroke-dasharray="2 2"/>'}${b.head ? '<circle cx="30" cy="22" r="9" fill="#0f7d4a"/>' : ''}${[...Array(b.leg || 0)].map((_, k) => { const side = k % 2 ? 1 : -1, y = 38 + (k >> 1) * 10; return `<line x1="${30 + side * 12}" y1="${y}" x2="${30 + side * 24}" y2="${y + 4}" stroke="#ffc23d" stroke-width="2"/>`; }).join('')}${[...Array(b.eye || 0)].map((_, k) => `<circle cx="${k ? 34 : 26}" cy="20" r="2" fill="#fff"/>`).join('')}${[...Array(b.antenna || 0)].map((_, k) => `<line x1="${k ? 33 : 27}" y1="14" x2="${k ? 40 : 20}" y2="4" stroke="#ffc23d" stroke-width="1.5"/>`).join('')}${b.tail ? '<line x1="30" y1="68" x2="30" y2="78" stroke="#ffc23d" stroke-width="2"/>' : ''}</svg>`;
    x.el.innerHTML = `<div class="pig"><div class="pigs">${s.b.map((b, i) => `<div class="pg ${i === s.t ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span>${draw(b)}</div>`).join('')}</div><div class="bigdie">${s.die || '–'}</div><p class="muted small">${esc(s.log)}</p><button class="btn hot" data-i="roll" ${x.can ? '' : 'disabled'}>Roll</button><p class="muted small">6 body · 5 head · 4 leg (six) · 3 eye (two) · 2 antenna (two) · 1 tail. Body first; eyes and antennae need the head.</p></div>`; x.on(() => x.act('roll')); } };

// ---------- Word Chain ----------
TB.wordchain = { seats: ['Seat 1', 'Seat 2', 'Seat 3', 'Seat 4'], needsWords: true, init: n => ({ n, used: [], strikes: Array(n).fill(0), t: 0, log: 'Start with any word of three or more letters.' }), turn: s => s.t,
  moves: s => TB.wordchain.result(s) ? [] : ['pass'],
  check(s, m) { if (TB.wordchain.result(s)) return false; if (m === 'pass') return true; if (!m || typeof m.w !== 'string') return false; const w = m.w.toLowerCase(); if (w.length < 3 || !Words.is(w) || s.used.includes(w)) return false; const last = s.used[s.used.length - 1]; return !last || w[0] === last[last.length - 1]; },
  play(s, m) { const n = cl(s), alive = i => n.strikes[i] < 3; const adv = () => { let j = s.t; do j = (j + 1) % s.n; while (!alive(j)); n.t = j; };
    if (m === 'pass') { n.strikes[s.t]++; n.log = `Seat ${s.t + 1} could not go: strike ${n.strikes[s.t]}`; adv(); return n; } n.used.push(m.w.toLowerCase()); n.log = `Seat ${s.t + 1} played ${m.w.toUpperCase()}`; adv(); return n; },
  result: s => { const a = s.strikes.map((v, i) => v < 3 ? i : -1).filter(i => i >= 0); return a.length === 1 ? { winner: a[0] } : null; },
  ai(s, level) { const last = s.used[s.used.length - 1], need = last ? last[last.length - 1] : 'abcdefghilmnoprst'[R(17)]; if (Math.random() < 0.04 * (11 - level)) return 'pass';
    const src = level >= 6 ? Words.list : Words.common; const cand = src.filter(w => w[0] === need && w.length >= 3 && !s.used.includes(w)); if (!cand.length) return 'pass'; const hard = level >= 8 ? cand.filter(w => 'xzqjv'.includes(w[w.length - 1])) : []; const pool = hard.length ? hard : cand; return { w: pool[R(pool.length)] }; },
  view(s, x) { const last = s.used[s.used.length - 1]; x.el.innerHTML = `<div class="ctable ghost"><div class="pigs">${s.strikes.map((v, i) => `<div class="pg ${s.t === i ? 'turn' : ''}"><span>${esc(x.names[i] || '')}</span><b>${'✕'.repeat(v) || '–'}</b></div>`).join('')}</div><div class="frag">${last ? last.toUpperCase() : '…'}</div><p class="center">${last ? `Next word must start with <b>${last[last.length - 1].toUpperCase()}</b>.` : ''} <span class="muted small">${esc(s.log)}</span></p>
    ${x.can ? `<form class="mform wcf"><input id="wcw" autocomplete="off" placeholder="Your word" aria-label="Your word"><button class="btn hot">Play</button><button type="button" class="btn ghost" data-i="pass">Give up this turn</button></form>` : ''}<p class="muted small">${s.used.slice(-12).map(w => w.toUpperCase()).join(' → ')}</p></div>`;
    x.on(() => x.act('pass')); const f = x.el.querySelector('.wcf'); if (f) { f.onsubmit = e => { e.preventDefault(); const w = f.querySelector('#wcw').value.trim().toLowerCase(); if (!TB.wordchain.check(s, { w })) { toast(s.used.includes(w) ? 'Already used.' : last && w[0] !== last[last.length - 1] ? 'Wrong first letter.' : 'Not in the dictionary.'); return; } x.act({ w }); }; f.querySelector('#wcw').focus(); } } };
